import type { AppDefinition } from '@/entities/app/types'
import { Badge } from './Badge'
import * as Icons from 'lucide-react'
import type { LucideIcon } from 'lucide-react'

type Props = {
  app: AppDefinition
  enabled: boolean
  onEnable: () => void
  onDisable: () => void
  onOpen: () => void
}

function DynamicIcon({ name }: { name: string }) {
  const Icon = (Icons as unknown as Record<string, LucideIcon>)[name]
  if (!Icon) return <Icons.Box size={20} />
  return <Icon size={20} />
}

export function AppMarketplaceCard({ app, enabled, onEnable, onDisable, onOpen }: Props) {
  return (
    <div className="bg-surface rounded-xl border border-border p-5 flex flex-col gap-3">
      <div className="flex items-start justify-between">
        <div className="p-2 rounded-xl bg-accent/10 text-accent">
          <DynamicIcon name={app.icon} />
        </div>
        <div className="flex gap-1">
          {app.premium && <Badge variant="warning">Pro</Badge>}
          <Badge variant={app.pricing === 'free' ? 'success' : 'default'}>
            {app.pricing ?? 'free'}
          </Badge>
        </div>
      </div>
      <div>
        <h3 className="font-semibold text-sm">{app.label}</h3>
        <p className="text-xs text-muted-foreground mt-0.5">{app.description}</p>
      </div>
      <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
        <span className="capitalize">{app.level}</span>
      </div>
      <div className="flex gap-2 mt-auto">
        {enabled ? (
          <>
            <button onClick={onOpen} className="flex-1 text-xs bg-accent text-accent-foreground py-1.5 rounded-lg hover:opacity-90">
              Open
            </button>
            <button onClick={onDisable} className="text-xs border border-border px-3 py-1.5 rounded-lg text-muted-foreground hover:text-foreground">
              Disable
            </button>
          </>
        ) : (
          <button onClick={onEnable} className="flex-1 text-xs border border-border py-1.5 rounded-lg text-muted-foreground hover:border-accent/50 hover:text-accent">
            Enable
          </button>
        )}
      </div>
    </div>
  )
}
